const rows = $input.all();
if (!rows || rows.length === 0) {
  return [{ json: { isLatest: false } }];
}
const latestId = String(rows[0].json.message_id || '');
const currentId = String($('Chatwoot Trigger').first().json.id || '');
return [{ json: { isLatest: latestId === currentId } }];

const trigger = $('Chatwoot Trigger').first().json;
const conversation = trigger.conversation || {};
const meta = trigger.meta || {};
const sender = meta.sender || {};
const kanbanTask = conversation.kanban_task || null;

// Tentar múltiplos caminhos para o nome do contato
const contactName =
  sender.name ||
  trigger.sender?.name ||
  conversation.meta?.sender?.name ||
  trigger.contact?.name ||
  'Lead WhatsApp';

// Tentar múltiplos caminhos para o telefone
const contactPhone =
  sender.phone_number ||
  trigger.sender?.phone_number ||
  conversation.meta?.sender?.phone_number ||
  trigger.contact?.phone_number ||
  '';

const rawEmail = sender.email || trigger.contact?.email || '';
const hasRealEmail = rawEmail.includes('@') && !rawEmail.includes('whatsapp');
const hubspotEmail = hasRealEmail
  ? rawEmail
  : `wa${conversation.id || '0'}@leads.lotusbusiness.com.br`;

return [{
  json: {
    conversationId: String(conversation.id || ''),
    messageContent: trigger.content || '',
    contactName,
    contactPhone,
    contactEmail: rawEmail,
    hubspotEmail,
    kanbanTaskId: kanbanTask ? String(kanbanTask.id) : null,
    kanbanCurrentStep: kanbanTask ? (kanbanTask.board_step_id || null) : null
  }
}];

// ================================================================
// PARSEAR E SCORING — LÓTUS BUSINESS v2
// Extrai SCORING_JSON do AI Agent e prepara dados para próximas etapas
// ================================================================

const output = $json.output || '';

// 1. Extrair SCORING_JSON
let scoring = {
  orcamento: false, prazo: null, decisor: null, necessidade: null,
  conhece: false, estagio: 'Contato Iniciado', notas: ''
};

const scoringMatch = output.match(/SCORING_JSON:(\{[^{}]+\})/);
if (scoringMatch) {
  try { scoring = JSON.parse(scoringMatch[1]); } catch(e) {}
}

// 2. Limpar texto da resposta (remove SCORING_JSON e = inicial que vaza do N8N)
const textResponse = output
  .replace(/\nSCORING_JSON:\{[^{}]+\}/g, '')
  .replace(/SCORING_JSON:\{[^{}]+\}/g, '')
  .replace(/^={1,3}\s*/m, '')  // remove = inicial se vazou da expressão N8N
  .trim();

// 3. Dados da conversa (nó anterior)
const info = $('Extrair Info da Conversa').first().json;

// 4. Mapeamento estágio → step_id do Kanban
// ATENÇÃO: Verifique os IDs reais em Chatwoot > Configurações > Kanban
// e ajuste os valores abaixo conforme seus step IDs reais
const estagioParaStepId = {
  'Novo Lead':            1,
  'Contato Iniciado':     2,
  'Qualificando':         3,
  'Engajado':             4,
  'Proposta Enviada':     5,
  'Negociação':           6,
  'Follow-up':            7,
  'Oportunidade Ganha':   8,
  'Oportunidade Perdida': 9
};

const stepId = estagioParaStepId[scoring.estagio] ?? 2;

// Mover kanban quando scoring foi extraído e estágio avançou
const deveMover = scoringMatch !== null && stepId > 1;

// 5. Score numérico 0-100
const score = [
  scoring.orcamento === true,
  scoring.prazo !== null,
  scoring.decisor !== null,
  scoring.necessidade !== null,
  scoring.conhece === true
].filter(Boolean).length * 20;

return [{
  json: {
    textResponse,
    conversationId: info.conversationId,
    contactEmail: info.contactEmail,
    hubspotEmail: info.hubspotEmail,
    contactName: info.contactName,
    contactPhone: info.contactPhone,
    deveMover,
    stepId,
    estagioFinal: scoring.estagio,
    score,
    notas: scoring.notas || '',
    kanbanTaskId: info.kanbanTaskId,
    scoringOrcamento: scoring.orcamento,
    scoringPrazo: scoring.prazo,
    scoringDecisor: scoring.decisor,
    scoringNecessidade: scoring.necessidade
  }
}];

// TODO: Buscar no HubSpot leads em 'Follow-up' que não responderam
// nas últimas 24h e enviar mensagem de reativação via Chatwoot.
// Retorna vazio para não disparar mensagens acidentalmente.
return [];
